  var vps=[["375x667","mobile OK"],["768x1024","tablet OK"],["1440x900","desktop OK"]];
  var v=vps[idx%vps.length];
  return "["+label+"] viewport "+v[0]+": "+v[1]+", no horizontal overflow";
}

